<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>飞机着陆：匀减速运动的可视化</title>
<style>
  :root{
    --bg:#edf2f8;
    --card:#ffffff;
    --ink:#14213d;
    --muted:#66758c;
    --line:#dbe4ef;
    --blue:#2563eb;
    --blue-soft:#dbeafe;
    --amber:#d97706;
    --amber-soft:#fff3d6;
    --red:#dc4c4c;
    --green:#0f9f6e;
    --shadow:0 10px 30px rgba(27,48,82,.08);
  }
  *{box-sizing:border-box}
  body{
    margin:0;
    background:
      radial-gradient(circle at 12% 0%, #e4efff 0, rgba(228,239,255,0) 34%),
      radial-gradient(circle at 92% 10%, #fff8e8 0, rgba(255,248,232,0) 30%),
      var(--bg);
    color:var(--ink);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", "PingFang SC", sans-serif;
    line-height:1.45;
  }
  .app{max-width:1280px;margin:0 auto;padding:22px 20px 38px}
  header{margin-bottom:14px}
  .kicker{font-size:12px;font-weight:800;letter-spacing:.16em;color:var(--blue);text-transform:uppercase}
  h1{font-size:clamp(24px,3.2vw,36px);line-height:1.15;margin:5px 0 0;letter-spacing:-.02em}
  .sub{margin:6px 0 0;color:var(--muted);font-size:14px}

  .problem-card{
    display:grid;
    grid-template-columns:minmax(240px,1.3fr) auto minmax(245px,.95fr);
    gap:14px 18px;
    align-items:center;
    background:linear-gradient(135deg,#ffffff 0%,#fbfdff 100%);
    border:1px solid var(--line);
    border-left:5px solid var(--blue);
    border-radius:16px;
    padding:14px 18px;
    box-shadow:var(--shadow);
    margin-bottom:14px;
  }
  .problem-main{display:flex;gap:10px;align-items:flex-start}
  .tag{
    flex:none;display:inline-flex;align-items:center;
    font-size:11px;font-weight:800;color:#fff;background:var(--blue);
    border-radius:999px;padding:4px 9px;margin-top:2px;
  }
  .problem-main p{margin:0;font-size:14px;color:#34445e}
  .problem-main b{color:var(--ink)}
  .chips{display:flex;gap:8px;flex-wrap:wrap}
  .chip{
    display:flex;align-items:center;gap:7px;
    border:1px solid #dbe7f7;background:#f7fbff;border-radius:10px;
    padding:7px 10px;white-space:nowrap;
  }
  .chip span{font-size:11px;font-weight:700;color:var(--muted)}
  .chip b{font-size:13px;color:var(--blue)}
  .chip.red{border-color:#f5d7d7;background:#fff8f8}
  .chip.red b{color:var(--red)}
  .chip.quiet{border-color:#e2e8f0;background:#f8fafc}
  .chip.quiet b{color:#475569}
  .asks{display:grid;gap:7px}
  .ask{
    display:flex;justify-content:space-between;align-items:center;gap:10px;
    border:1px solid #e5ebf3;background:#f8fafc;border-radius:10px;
    padding:6px 10px;font-size:12px;color:var(--muted);
  }
  .ask b{font-size:13px;color:#4b5b72;font-weight:700;transition:.2s ease}
  .ask b.revealed{
    color:#fff;background:var(--green);border-radius:7px;padding:3px 8px;
  }

  .step-rail{
    display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;
  }
  .step-btn{
    appearance:none;border:1px solid var(--line);background:#fff;color:#53627a;
    border-radius:999px;padding:8px 12px 8px 9px;font-size:12px;font-weight:700;
    display:inline-flex;align-items:center;gap:7px;cursor:pointer;
    transition:.18s ease;box-shadow:0 2px 6px rgba(27,48,82,.03);
  }
  .step-btn:hover{border-color:#b9cbea;transform:translateY(-1px)}
  .step-btn .num{
    display:inline-grid;place-items:center;width:21px;height:21px;border-radius:50%;
    background:#edf2f8;color:#53627a;font-size:11px;font-weight:800;
  }
  .step-btn.active{background:var(--blue);border-color:var(--blue);color:#fff;box-shadow:0 7px 16px rgba(37,99,235,.22)}
  .step-btn.active .num{background:rgba(255,255,255,.2);color:#fff}

  .layout{
    display:grid;
    grid-template-columns:minmax(0,1.58fr) minmax(360px,1fr);
    gap:16px;align-items:start;
  }
  .card{
    background:var(--card);border:1px solid var(--line);border-radius:18px;
    box-shadow:var(--shadow);overflow:hidden;
  }
  .scene-card{padding:14px 14px 12px}
  .card-top{
    display:flex;justify-content:space-between;align-items:center;gap:12px;
    margin-bottom:8px;min-height:24px;
  }
  .card-top .left-inline{display:flex;align-items:center;gap:9px;flex-wrap:wrap}
  .section-label{font-size:12px;font-weight:800;letter-spacing:.08em;color:var(--blue)}
  .small-note{font-size:11px;color:#8a97a8}
  .status-pill{
    font-size:11px;font-weight:700;color:#345179;background:#edf5ff;
    border:1px solid #d6e6ff;border-radius:999px;padding:4px 9px;white-space:nowrap;
  }
  .scene-card svg{display:block;width:100%;height:auto;border-radius:12px;background:#f8fbff}
  .timeline-wrap{margin-top:9px;border-top:1px dashed #e3eaf3;padding-top:8px}
  .mini-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:2px}
  .mini-head span:first-child{font-size:11px;font-weight:800;color:#53627a}
  .mini-head span:last-child{font-size:11px;color:#8a97a8}
  #timeline{display:block;width:100%;height:auto}
  input[type=range]{
    display:block;width:100%;margin:2px 0 0;accent-color:var(--blue);height:24px;cursor:pointer;
  }
  .controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:5px}
  .btn{
    appearance:none;border:1px solid var(--line);background:#fff;color:#43526b;
    border-radius:10px;padding:8px 13px;font-size:12px;font-weight:800;cursor:pointer;
    transition:.16s ease;
  }
  .btn:hover{border-color:#b9cbea;background:#f9fbff}
  .btn.primary{background:var(--blue);border-color:var(--blue);color:#fff;box-shadow:0 7px 15px rgba(37,99,235,.2)}
  .btn.primary:hover{background:#1d4fd8;border-color:#1d4fd8}
  .control-hint{font-size:11px;color:#8a97a8;margin-left:2px}

  .side{display:flex;flex-direction:column;gap:16px}
  .chart-card{padding:14px 14px 12px}
  .chart-card svg{display:block;width:100%;height:auto;border-radius:12px;background:#fbfdff}
  .readouts{
    display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:8px;
  }
  .readout{
    background:#f7fafd;border:1px solid #e4ebf4;border-radius:10px;padding:7px 8px;
    display:flex;align-items:baseline;justify-content:space-between;gap:6px;
  }
  .readout span{font-size:10px;font-weight:800;color:#7b899c}
  .readout strong{font-size:15px;color:#27405f;line-height:1}
  .readout small{font-size:10px;color:#8a97a8;font-weight:700}
  .last-readout{
    display:none;margin-top:8px;border-radius:10px;padding:8px 10px;
    background:var(--amber-soft);border:1px solid #f4d79a;color:#8a5a13;
    font-size:12px;font-weight:600;
  }
  .last-readout strong{font-size:15px;color:#b45309}
  .last-readout.final{background:#fff6df;border-color:#f1c86d}

  .formula-card{padding:15px 16px 16px;min-height:190px}
  .formula-head{display:flex;align-items:center;gap:8px;margin-bottom:8px}
  .formula-head h3{margin:0;font-size:17px;line-height:1.25;letter-spacing:-.01em}
  .step-tag{
    display:inline-flex;align-items:center;border-radius:999px;padding:3px 8px;
    background:#edf5ff;color:var(--blue);font-size:10px;font-weight:800;white-space:nowrap;
  }
  .formula-line{
    font-family:"Cambria Math","Times New Roman",serif;
    font-size:16px;color:#263b5c;margin:7px 0;
    letter-spacing:.01em;
  }
  .formula-line strong{color:var(--blue)}
  .eq-grid{display:grid;gap:4px;margin:8px 0}
  .eq-row{display:flex;align-items:baseline;gap:8px;font-size:13px;color:#43526b;flex-wrap:wrap}
  .eq-label{min-width:58px;font-size:11px;font-weight:800;color:#8a97a8}
  .eq{font-family:"Cambria Math","Times New Roman",serif;font-size:15px;color:#27405f}
  .answer-chip{
    display:inline-flex;align-items:baseline;gap:8px;margin:10px 0 4px;
    background:#eaf8f2;border:1px solid #b7ebd6;color:#0c7a55;
    border-radius:10px;padding:8px 12px;font-family:"Cambria Math","Times New Roman",serif;
    font-size:16px;
  }
  .answer-chip strong{font-size:22px;line-height:1;color:#087f57}
  .answer-chip.amber-chip{background:#fff6df;border-color:#f2ce7f;color:#9a5b08}
  .answer-chip.amber-chip strong{color:#b45309}
  .hint{margin:9px 0 0;font-size:12px;color:#66758c;line-height:1.55}
  .demo-btn{
    appearance:none;border:1px solid #c8d9f4;background:#f3f8ff;color:#255fbe;
    border-radius:9px;padding:7px 10px;font-size:12px;font-weight:800;cursor:pointer;
    margin-top:10px;transition:.16s ease;
  }
  .demo-btn:hover{background:#e9f2ff;border-color:#aac4ec}
  .muted{color:#8a97a8;font-weight:500}
  .red-text{color:var(--red)}
  .blue-text{color:var(--blue)}
  .amber-text{color:#b45309}

  svg text{font-family:inherit}
  .svg-small{font-size:11px;fill:#7b899c;font-weight:600}
  .svg-label{font-size:12px;fill:#51617a;font-weight:700}
  .svg-blue{fill:var(--blue)}
  .svg-amber{fill:#b45309}
  .svg-red{fill:var(--red)}
  .svg-muted{fill:#8a97a8}
  .svg-strong{font-size:13px;font-weight:800}
  .axis-title{font-size:11px;fill:#8a97a8;font-weight:700}

  @media (max-width: 980px){
    .layout{grid-template-columns:1fr}
    .problem-card{grid-template-columns:1fr}
    .asks{grid-template-columns:1fr 1fr}
  }
  @media (max-width: 620px){
    .app{padding:16px 12px 28px}
    .asks{grid-template-columns:1fr}
    .step-btn{font-size:11px;padding:7px 10px 7px 7px}
    .readouts{grid-template-columns:1fr 1fr 1fr}
    .readout{padding:6px}
    .readout strong{font-size:13px}
    .formula-line{font-size:15px}
  }
</style>
</head>
<body>
<div class="app">
  <header>
    <div class="kicker">匀变速直线运动 · 交互可视化</div>
    <h1>飞机着陆：让速度图“走”成距离</h1>
    <p class="sub">拖动时间，观察飞机位置、速度箭头和 v-t 图如何同步变化。</p>
  </header>

  <section class="problem-card" aria-label="题目条件与待求量">
    <div class="problem-main">
      <span class="tag">题目</span>
      <p>飞机着陆后以 <b>6 m/s²</b> 的加速度做匀减速直线运动直至静止。其着陆速度为 <b>36 m/s</b>。</p>
    </div>
    <div class="chips" aria-label="已知量">
      <div class="chip"><span>v₀</span><b>36 m/s</b></div>
      <div class="chip red"><span>减速大小</span><b>6 m/s²</b></div>
      <div class="chip quiet"><span>v末</span><b>0</b></div>
    </div>
    <div class="asks">
      <div class="ask"><span>求 (1)</span><b id="ans1">滑行距离 ?</b></div>
      <div class="ask"><span>求 (2)</span><b id="ans2">最后 4 s 位移 ?</b></div>
    </div>
  </section>

  <nav class="step-rail" aria-label="解题步骤">
    <button class="step-btn active" data-step="0"><span class="num">0</span>建立运动图</button>
    <button class="step-btn" data-step="1"><span class="num">1</span>求停稳时刻</button>
    <button class="step-btn" data-step="2"><span class="num">2</span>第 (1) 问</button>
    <button class="step-btn" data-step="3"><span class="num">3</span>最后 4 s 区间</button>
    <button class="step-btn" data-step="4"><span class="num">4</span>第 (2) 问</button>
  </nav>

  <main class="layout">
    <section class="card scene-card" aria-label="跑道与飞机运动示意图">
      <div class="card-top">
        <div class="left-inline">
          <span class="section-label">跑道示意</span>
          <span class="status-pill" id="statusPill">t = 0.0 s</span>
        </div>
        <span class="small-note">位置基准：机头</span>
      </div>

      <svg id="scene" viewBox="0 0 960 320" role="img" aria-label="飞机在跑道上向右滑行并减速">
        <defs>
          <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#e9f4ff"/>
            <stop offset="1" stop-color="#f9fcff"/>
          </linearGradient>
          <marker id="arrowBlue" markerUnits="userSpaceOnUse" markerWidth="13" markerHeight="13" refX="11" refY="6.5" orient="auto">
            <path d="M0 0 L13 6.5 L0 13 Z" fill="#2563eb"/>
          </marker>
          <marker id="arrowRed" markerUnits="userSpaceOnUse" markerWidth="11" markerHeight="11" refX="9.5" refY="5.5" orient="auto">
            <path d="M0 0 L11 5.5 L0 11 Z" fill="#dc4c4c"/>
          </marker>
        </defs>

        <rect x="0" y="0" width="960" height="210" fill="url(#sky)"/>
        <g opacity=".65">
          <path d="M108 61 C120 48 142 48 154 61 C168 55 185 62 187 74 L104 74 C98 68 101 64 108 61 Z" fill="#ffffff"/>
          <path d="M730 44 C740 34 758 34 768 44 C779 40 792 46 794 56 L726 56 C721 51 723 47 730 44 Z" fill="#ffffff"/>
        </g>
        <text x="34" y="38" class="svg-small">运动方向 →</text>

        <rect x="28" y="210" width="904" height="70" rx="6" fill="#334155"/>
        <rect x="28" y="210" width="904" height="9" fill="#475569"/>
        <line x1="37" y1="244" x2="922" y2="244" stroke="#64748b" stroke-width="2" stroke-dasharray="18 18" opacity=".55"/>

        <rect id="lastZoneFull" x="580" y="210" width="320" height="70" fill="#f59e0b" opacity=".16" style="display:none"/>
        <rect id="lastZoneDone" x="580" y="210" width="0" height="70" fill="#f59e0b" opacity=".38" style="display:none"/>

        <line x1="180" y1="210" x2="180" y2="280" stroke="#ffffff" stroke-width="3.5" stroke-dasharray="7 7"/>
        <line id="stopLine" x1="900" y1="160" x2="900" y2="280" stroke="#fbbf24" stroke-width="3" stroke-dasharray="8 7" style="display:none"/>

        <g id="lastStartTick" style="display:none">
          <line x1="0" y1="280" x2="0" y2="291" stroke="#d97706" stroke-width="2.5"/>
          <text x="0" y="306" text-anchor="middle" class="svg-label svg-amber">60 m</text>
        </g>

        <text x="180" y="306" text-anchor="middle" class="svg-label svg-muted">起点 0 m（机头）</text>
        <text id="stopLabel" x="900" y="306" text-anchor="middle" class="svg-label svg-amber" style="display:none">108 m</text>

        <g id="planeGroup" transform="translate(180 243)">
          <ellipse cx="-36" cy="27" rx="47" ry="6" fill="#0b1b33" opacity=".18"/>
          <path d="M 0 0 C -12 -10 -55 -12 -78 -4 L -78 4 C -55 10 -12 8 0 0 Z" fill="#f2f7ff" stroke="#2d537f" stroke-width="2"/>
          <path d="M -38 -3 L -64 -27 L -51 -27 L -22 -3 Z" fill="#cfe1f9" stroke="#2d537f" stroke-width="1.4"/>
          <path d="M -38 3 L -64 27 L -51 27 L -22 3 Z" fill="#cfe1f9" stroke="#2d537f" stroke-width="1.4"/>
          <path d="M -72 -2 L -88 -20 L -77 -20 L -58 -2 Z" fill="#cfe1f9" stroke="#2d537f" stroke-width="1.4"/>
          <path d="M -72 2 L -88 20 L -77 20 L -58 2 Z" fill="#cfe1f9" stroke="#2d537f" stroke-width="1.4"/>
          <circle cx="-17" cy="-4" r="2.2" fill="#2d537f"/>
          <circle cx="-26" cy="-4" r="2.2" fill="#2d537f"/>
          <circle cx="-35" cy="-4" r="2.2" fill="#2d537f"/>
          <circle cx="0" cy="0" r="3.2" fill="#2563eb" stroke="#ffffff" stroke-width="1.5"/>
        </g>

        <g id="velGroup">
          <line id="velArrow" x1="162" y1="136" x2="243" y2="136" stroke="#2563eb" stroke-width="7" stroke-linecap="round" marker-end="url(#arrowBlue)"/>
          <text id="velLabel" x="162" y="116" class="svg-label svg-blue">v = 36.0 m/s</text>
