        <g id="accGroup" transform="translate(162 180)">
          <line x1="0" y1="0" x2="-62" y2="0" stroke="#dc4c4c" stroke-width="5" stroke-linecap="round" marker-end="url(#arrowRed)"/>
          <text x="-30" y="-9" text-anchor="middle" class="svg-label svg-red">a</text>
        </g>

        <g id="lastSceneBadge" transform="translate(740 0)" style="display:none">
          <line x1="0" y1="102" x2="0" y2="210" stroke="#d97706" stroke-width="1.5" stroke-dasharray="4 5" opacity=".65"/>
          <rect x="-91" y="70" width="182" height="32" rx="16" fill="#fff7e6" stroke="#f59e0b" stroke-width="1.5"/>
          <text id="lastSceneBadgeText" x="0" y="91" text-anchor="middle" class="svg-label svg-amber">最后 4 s 区间</text>
        </g>
      </svg>

      <div class="timeline-wrap">
        <div class="mini-head">
          <span>时间轴</span>
          <span>拖动滑块，观察同一时刻的飞机、速度与面积</span>
        </div>
        <svg id="timeline" viewBox="0 0 960 98" role="img" aria-label="时间轴">
          <rect id="lastTimeZone" x="366.67" y="16" width="533.33" height="31" rx="7" fill="#f59e0b" opacity=".16" style="display:none"/>
          <line x1="100" y1="34" x2="900" y2="34" stroke="#9aa9bd" stroke-width="2"/>
          <g id="timeTicks"></g>
          <line id="timeMarker" x1="100" y1="16" x2="100" y2="52" stroke="#2563eb" stroke-width="3" stroke-linecap="round"/>
          <circle id="timeDot" cx="100" cy="34" r="7" fill="#2563eb" stroke="#ffffff" stroke-width="2.5"/>
          <g id="lastBracket" style="display:none">
            <line id="bracketLine" x1="366.67" y1="72" x2="900" y2="72" stroke="#d97706" stroke-width="2"/>
            <line id="bracketTickL" x1="366.67" y1="66" x2="366.67" y2="78" stroke="#d97706" stroke-width="2"/>
            <line id="bracketTickR" x1="900" y1="66" x2="900" y2="78" stroke="#d97706" stroke-width="2"/>
            <text id="bracketText" x="633.33" y="91" text-anchor="middle" class="svg-label svg-amber">最后 4 s</text>
          </g>
        </svg>
        <input id="timeSlider" type="range" min="0" max="4" step="0.01" value="0" aria-label="飞机着陆后的时间，单位为秒">
      </div>

      <div class="controls">
        <button class="btn primary" id="playBtn">播放</button>
        <button class="btn" id="resetBtn">重置</button>
        <span class="control-hint">播放时速度箭头会缩短，飞机逐渐停下。</span>
      </div>
    </section>

    <aside class="side">
      <section class="card chart-card" aria-label="速度时间图像">
        <div class="card-top">
          <div class="left-inline">
            <span class="section-label">v-t 图</span>
            <span class="small-note">线下面积 = 位移</span>
          </div>
          <span class="small-note">斜率 = 加速度</span>
        </div>

        <svg id="chart" viewBox="0 0 440 310" role="img" aria-label="速度随时间线性减小到零的图像">
          <rect x="0" y="0" width="440" height="310" rx="12" fill="#fbfdff"/>

          <g id="chartGrid"></g>

          <polygon id="lastRegion" points="173.33,252 173.33,112 410,252" fill="#f59e0b" fill-opacity=".07" stroke="#d97706" stroke-width="1.2" stroke-dasharray="5 5" style="display:none"/>
          <polygon id="areaMain" points="" fill="#2563eb" fill-opacity=".18" stroke="none" style="display:none"/>
          <polygon id="areaLast" points="" fill="#f59e0b" fill-opacity=".32" stroke="none" style="display:none"/>

          <line id="vtLine" x1="55" y1="42" x2="410" y2="252" stroke="#2563eb" stroke-width="3.2" stroke-linecap="round" style="display:none"/>

          <line x1="55" y1="252" x2="410" y2="252" stroke="#8a97a8" stroke-width="1.5"/>
          <line x1="55" y1="42" x2="55" y2="252" stroke="#8a97a8" stroke-width="1.5"/>

          <g id="stopMark" style="display:none">
            <line x1="410" y1="42" x2="410" y2="252" stroke="#94a3b8" stroke-width="1.2" stroke-dasharray="4 4"/>
            <circle cx="410" cy="252" r="5" fill="#ffffff" stroke="#2563eb" stroke-width="2.5"/>
            <text x="398" y="238" text-anchor="end" class="svg-small svg-blue">t = 6 s</text>
          </g>

          <g id="t2Mark" style="display:none">
            <line x1="173.33" y1="42" x2="173.33" y2="252" stroke="#d97706" stroke-width="1.2" stroke-dasharray="4 4"/>
            <text x="173.33" y="286" text-anchor="middle" class="svg-small svg-amber">2 s</text>
          </g>

          <line id="vGuide" x1="55" y1="42" x2="55" y2="252" stroke="#7ca8f7" stroke-width="1.4" stroke-dasharray="4 4"/>
          <line id="hGuide" x1="55" y1="42" x2="55" y2="42" stroke="#7ca8f7" stroke-width="1.4" stroke-dasharray="4 4"/>
          <circle id="point" cx="55" cy="42" r="5.5" fill="#2563eb" stroke="#ffffff" stroke-width="2.5"/>
          <text id="pointLabel" x="66" y="59" class="svg-small svg-blue">v=36.0</text>

          <text id="areaLabel1" x="128" y="190" text-anchor="middle" class="svg-label svg-blue" style="display:none">60 m</text>
          <text id="areaLabel2" x="300" y="218" text-anchor="middle" class="svg-label svg-amber" style="display:none">48 m</text>
          <text id="areaLabelTotal" x="232" y="151" text-anchor="middle" class="svg-label svg-blue" style="display:none">108 m</text>

          <g id="chartXTicks"></g>
          <g id="chartYTicks"></g>

          <text x="232" y="300" text-anchor="middle" class="axis-title">t / s</text>
          <text x="14" y="150" transform="rotate(-90 14 150)" text-anchor="middle" class="axis-title">v / (m·s⁻¹)</text>
          <text x="315" y="58" text-anchor="middle" class="svg-small svg-muted">斜率 = −6 m/s²</text>
        </svg>

        <div class="readouts" aria-label="当前读数">
          <div class="readout"><span>t</span><strong id="readT">0.0</strong><small>s</small></div>
          <div class="readout"><span>v</span><strong id="readV">36.0</strong><small>m/s</small></div>
          <div class="readout"><span>滑行</span><strong id="readX">0.0</strong><small>m</small></div>
        </div>
        <div class="last-readout" id="lastReadout"></div>
      </section>

      <section class="card formula-card" id="formulaCard" aria-live="polite"></section>
    </aside>
  </main>
</div>

<script>
  (function(){
    "use strict";

    const V0 = 36;
    const A = -6;
    const T_STOP = 6;
    const TOTAL_X = 108;
    const LAST_START_T = 2;
    const LAST_START_X = 60;
    const LAST_DISP = 48;

    const SCENE_X0 = 180;
    const SCENE_X1 = 900;
    const SCENE_Y = 243;
    const SCENE_SCALE = (SCENE_X1 - SCENE_X0) / TOTAL_X;

    const TIME_X0 = 100;
    const TIME_X1 = 900;

    const CH = { left:55, right:410, top:42, bottom:252 };

    const state = {
      t: 0,
      step: 0,
      showLast: false,
      playing: false,
      animStart: 0,
      animFrom: 0,
      animTo: 0,
      animDur: 0,
      lastViewMax: null
    };

    const $ = (id) => document.getElementById(id);

    const els = {
      ans1: $("ans1"),
      ans2: $("ans2"),
      statusPill: $("statusPill"),
      scenePlane: $("planeGroup"),
      velArrow: $("velArrow"),
      velLabel: $("velLabel"),
      accGroup: $("accGroup"),
      lastZoneFull: $("lastZoneFull"),
      lastZoneDone: $("lastZoneDone"),
      lastStartTick: $("lastStartTick"),
      stopLine: $("stopLine"),
      stopLabel: $("stopLabel"),
      lastSceneBadge: $("lastSceneBadge"),
      lastSceneBadgeText: $("lastSceneBadgeText"),
      timeMarker: $("timeMarker"),
      timeDot: $("timeDot"),
      lastTimeZone: $("lastTimeZone"),
      lastBracket: $("lastBracket"),
      bracketLine: $("bracketLine"),
      bracketTickL: $("bracketTickL"),
      bracketTickR: $("bracketTickR"),
      bracketText: $("bracketText"),
      timeTicks: $("timeTicks"),
      timeSlider: $("timeSlider"),
      readT: $("readT"),
      readV: $("readV"),
      readX: $("readX"),
      lastReadout: $("lastReadout"),
      areaMain: $("areaMain"),
      areaLast: $("areaLast"),
      lastRegion: $("lastRegion"),
      t2Mark: $("t2Mark"),
      stopMark: $("stopMark"),
      vtLine: $("vtLine"),
      vGuide: $("vGuide"),
      hGuide: $("hGuide"),
      point: $("point"),
      pointLabel: $("pointLabel"),
      areaLabel1: $("areaLabel1"),
      areaLabel2: $("areaLabel2"),
      areaLabelTotal: $("areaLabelTotal"),
      chartGrid: $("chartGrid"),
      chartXTicks: $("chartXTicks"),
      chartYTicks: $("chartYTicks"),
      formulaCard: $("formulaCard"),
      stepBtns: document.querySelectorAll(".step-btn"),
      playBtn: $("playBtn"),
      resetBtn: $("resetBtn")
    };

    function getViewMax(){
      return state.step >= 1 ? T_STOP : 4;
    }

    function posAt(t){
      return V0 * t + 0.5 * A * t * t;
    }
    function velAt(t){
      return Math.max(0, V0 + A * t);
    }
    function scenePos(s){
      return SCENE_X0 + s * SCENE_SCALE;
    }
    function sceneX(t){
      return scenePos(posAt(t));
    }
    function timeX(t){
      return TIME_X0 + (t / getViewMax()) * (TIME_X1 - TIME_X0);
    }
    function chartX(t){
      return CH.left + (t / getViewMax()) * (CH.right - CH.left);
    }
    function chartY(v){
      return CH.bottom - (v / V0) * (CH.bottom - CH.top);
    }
    function clampT(t){
      return Math.max(0, Math.min(getViewMax(), t));
    }

    function buildTimeTicks(viewMax){
      let html = "";
      const n = Math.round(viewMax);
      for(let i=0;i<=n;i++){
        const x = timeX(i);
        const major = (i % 2 === 0);
        html += `<line x1="${x}" y1="${major ? 26 : 29}" x2="${x}" y2="${major ? 42 : 39}" stroke="#9aa9bd" stroke-width="${major ? 2 : 1.2}"/>`;
        html += `<text x="${x}" y="${major ? 62 : 58}" text-anchor="middle" class="${major ? "svg-label" : "svg-small"}">${i}</text>`;
      }
      els.timeTicks.innerHTML = html;
    }

    function buildChartTicks(viewMax){
      let grid = "";
      let xLabels = "";
      let yLabels = "";
      const n = Math.round(viewMax);

      for(let i=0;i<=n;i++){
        const x = chartX(i);
        const major = (i % 2 === 0);
        grid += `<line x1="${x}" y1="${CH.top}" x2="${x}" y2="${CH.bottom}" stroke="#e8eef6" stroke-width="${major ? 1.2 : 1}"/>`;
        xLabels += `<text x="${x}" y="272" text-anchor="middle" class="${major ? "svg-label" : "svg-small"}">${i}</text>`;
      }

      for(let v=0; v<=V0; v+=12){
        const y = chartY(v);
        grid += `<line x1="${CH.left}" y1="${y}" x2="${CH.right}" y2="${y}" stroke="#e8eef6" stroke-width="1"/>`;
        yLabels += `<text x="${CH.left - 10}" y="${y + 4}" text-anchor="end" class="svg-small">${v}</text>`;
      }

      els.chartGrid.innerHTML = grid;
      els.chartXTicks.innerHTML = xLabels;
      els.chartYTicks.innerHTML = yLabels;
    }

    function updateStepButtons(){
      els.stepBtns.forEach(btn => {
        const s = Number(btn.dataset.step);
        btn.classList.toggle("active", s === state.step);
      });
    }

    function updateAnswers(){
      const firstKnown = state.step >= 2;
      const secondKnown = state.step >= 4;
      els.ans1.textContent = firstKnown ? "108 m" : "滑行距离 ?";
      els.ans1.classList.toggle("revealed", firstKnown);
      els.ans2.textContent = secondKnown ? "48 m" : "最后 4 s 位移 ?";
      els.ans2.classList.toggle("revealed", secondKnown);
    }

    function renderFormula(){
      let html = "";
      if(state.step === 0){
        html = `
          <div class="formula-head">
            <span class="step-tag">观察</span>
            <h3>先把方向与符号定下来</h3>
          </div>
          <div class="formula-line">取运动方向为正方向</div>
          <div class="formula-line">a = −6 m/s² <span class="muted">（题中 6 m/s² 是减速大小）</span></div>
          <div class="eq-grid">
            <div class="eq-row"><span class="eq-label">初速度</span><span class="eq blue-text">v₀ = +36 m/s</span></div>
            <div class="eq-row"><span class="eq-label">末速度</span><span class="eq">v = 0</span></div>
          </div>
          <p class="hint">飞机沿正方向运动，加速度方向与运动方向相反，所以 a 取负。先拖动时间滑块观察前 4 s 的速度与位置变化。</p>
        `;
      } else if(state.step === 1){
        html = `
          <div class="formula-head">
            <span class="step-tag">第 1 步</span>
            <h3>求停稳所需时间</h3>
          </div>
          <div class="formula-line">v = v₀ + at</div>
          <div class="formula-line">0 = 36 − 6t</div>
          <div class="answer-chip">t停 = <strong>6 s</strong></div>
          <p class="hint">看 v-t 图：直线与横轴相交的时刻，就是速度减到 0、飞机停稳的时刻。此时时间轴才展开到 6 s。</p>
          <button class="demo-btn" data-demo="0,6">从 0 走到停稳</button>
        `;
      } else if(state.step === 2){
        html = `
          <div class="formula-head">
            <span class="step-tag">第 (1) 问</span>
            <h3>全程滑行距离</h3>
          </div>
          <div class="formula-line">位移 = v-t 图线下面积</div>
          <div class="formula-line">s = ½ × 36 × 6</div>
          <div class="answer-chip">s = <strong>108 m</strong></div>
          <p class="hint">蓝色三角形的面积就是全程滑行距离。拖动时间滑块，可以看到面积从 0 逐渐长满整个三角形。</p>
          <button class="demo-btn" data-demo="0,6">回放全程滑行</button>
        `;
      } else if(state.step === 3){
        html = `
          <div class="formula-head">
            <span class="step-tag">第 3 步</span>
            <h3>最后 4 s 从哪个时刻开始？</h3>
          </div>
          <div class="formula-line">t起 = 6 − 4 = <strong>2 s</strong></div>
          <div class="formula-line">v(2) = 36 − 6×2 = <strong>24 m/s</strong></div>
          <div class="formula-line" style="font-size:15px">x(2) = 36×2 − ½×6×2² = 60 m</div>
          <p class="hint">黄色区域就是最后 4 s。它在跑道上从 60 m 处开始，一直延伸到 108 m 处的停止点。</p>
          <button class="demo-btn" data-demo="2,6">扫过最后 4 s</button>
        `;
      } else {
        html = `
          <div class="formula-head">
            <span class="step-tag">第 (2) 问</span>
            <h3>最后 4 s 的位移</h3>
          </div>
          <div class="formula-line">s后4 = ½ × (24 + 0) × 4</div>
          <div class="answer-chip amber-chip">s后4 = <strong>48 m</strong></div>
          <p class="hint">核对：前 2 s 滑行 60 m，最后 4 s 滑行 48 m，60 + 48 = 108 m，正好是全程距离。</p>
          <button class="demo-btn" data-demo="2,6">回放最后 4 s</button>
        `;
      }
      els.formulaCard.innerHTML = html;
    }

    function underCurvePoints(t1, t2){
      if(t2 <= t1 + 0.0001) return "";
      const x1 = chartX(t1);
      const x2 = chartX(t2);
      const y1 = chartY(velAt(t1));
      const y2 = chartY(velAt(t2));
      return `${x1},${CH.bottom} ${x1},${y1} ${x2},${y2} ${x2},${CH.bottom}`;
    }

    function updateAreas(t){
      const showLast = state.showLast;
      const mainEnd = showLast ? Math.min(t, LAST_START_T) : t;
      const mainPoints = underCurvePoints(0, mainEnd);

      if(mainPoints){
        els.areaMain.setAttribute("points", mainPoints);
        els.areaMain.style.display = "";
      } else {
        els.areaMain.style.display = "none";
      }

      if(showLast){
        const x2 = chartX(LAST_START_T);
        const y2 = chartY(velAt(LAST_START_T));
        const x6 = chartX(T_STOP);
        els.lastRegion.setAttribute("points", `${x2},${CH.bottom} ${x2},${y2} ${x6},${CH.bottom}`);
        els.lastRegion.style.display = "";
        els.t2Mark.style.display = "";
      } else {
        els.lastRegion.style.display = "none";
        els.t2Mark.style.display = "none";
      }

      if(showLast && t > LAST_START_T + 0.001){
        els.areaLast.setAttribute("points", underCurvePoints(LAST_START_T, t));
        els.areaLast.style.display = "";
      } else {
        els.areaLast.style.display = "none";
      }

      const showTotalLabel = state.step === 2 && t >= T_STOP - 0.005;
      els.areaLabelTotal.style.display = showTotalLabel ? "" : "none";
      if(showTotalLabel){
        els.areaLabelTotal.setAttribute("x", chartX(3));
        els.areaLabelTotal.setAttribute("y", CH.bottom - 100);
      }

      const showFirstPart = showLast && t >= LAST_START_T - 0.001;
      els.areaLabel1.style.display = showFirstPart ? "" : "none";
      if(showFirstPart){
        els.areaLabel1.setAttribute("x", chartX(1));
        els.areaLabel1.setAttribute("y", CH.bottom - 55);
      }

      const showLastPart = state.step === 4 && t >= T_STOP - 0.005;
      els.areaLabel2.style.display = showLastPart ? "" : "none";
      if(showLastPart){
        els.areaLabel2.setAttribute("x", chartX(4.6));
        els.areaLabel2.setAttribute("y", CH.bottom - 32);
      }
    }

    function updateChart(t){
      const v = velAt(t);
      const px = chartX(t);
      const py = chartY(v);

      els.point.setAttribute("cx", px);
      els.point.setAttribute("cy", py);

      els.vGuide.setAttribute("x1", px);
      els.vGuide.setAttribute("x2", px);
      els.vGuide.setAttribute("y1", py);
      els.vGuide.setAttribute("y2", CH.bottom);

      els.hGuide.setAttribute("x1", CH.left);
      els.hGuide.setAttribute("x2", px);
      els.hGuide.setAttribute("y1", py);
      els.hGuide.setAttribute("y2", py);

      let lx = px + 10;
      let ly = py - 10;
      let anchor = "start";
      if(px > 340){
        lx = px - 10;
        anchor = "end";
      }
      if(py < 62){
        ly = py + 22;
      }
      els.pointLabel.setAttribute("x", lx);
      els.pointLabel.setAttribute("y", ly);
      els.pointLabel.setAttribute("text-anchor", anchor);
      els.pointLabel.textContent = `v=${v.toFixed(1)}`;

      if(state.step >= 1){
        els.vtLine.style.display = "";
        els.vtLine.setAttribute("x1", chartX(0));
        els.vtLine.setAttribute("y1", chartY(V0));
        els.vtLine.setAttribute("x2", chartX(T_STOP));
        els.vtLine.setAttribute("y2", chartY(0));
      } else if(t > 0.01){
        els.vtLine.style.display = "";
        els.vtLine.setAttribute("x1", chartX(0));
        els.vtLine.setAttribute("y1", chartY(V0));
        els.vtLine.setAttribute("x2", px);
        els.vtLine.setAttribute("y2", py);
      } else {
        els.vtLine.style.display = "none";
      }

      els.stopMark.style.display = state.step >= 1 ? "" : "none";
      updateAreas(t);
    }

    function updateScene(t){
      const v = velAt(t);
      const planeX = sceneX(t);

      els.scenePlane.setAttribute("transform", `translate(${planeX} ${SCENE_Y})`);

      const arrowStart = planeX - 18;
      if(v > 0.05){
        const arrowLen = Math.max(5, v * 2.25);
        els.velArrow.style.display = "";
        els.velArrow.setAttribute("x1", arrowStart);
        els.velArrow.setAttribute("x2", arrowStart + arrowLen);
        els.velLabel.style.display = "";
        els.velLabel.setAttribute("x", arrowStart);
        els.velLabel.setAttribute("text-anchor", "start");
        els.velLabel.textContent = `v = ${v.toFixed(1)} m/s`;
        els.accGroup.style.display = "";
        els.accGroup.setAttribute("transform", `translate(${arrowStart} 180)`);
      } else {
        els.velArrow.style.display = "none";
        els.velLabel.style.display = "";
        els.velLabel.setAttribute("x", planeX - 8);
        els.velLabel.setAttribute("text-anchor", "end");
        els.velLabel.textContent = "v = 0（已停稳）";
        els.accGroup.style.display = "none";
      }

      const stopVisible = state.step >= 2;
      els.stopLine.style.display = stopVisible ? "" : "none";
      els.stopLabel.style.display = stopVisible ? "" : "none";
      els.stopLabel.textContent = "108 m";

      if(state.showLast){
        const lastStartSceneX = scenePos(LAST_START_X);
        const stopX = SCENE_X1;
        els.lastZoneFull.style.display = "";
        els.lastZoneFull.setAttribute("x", lastStartSceneX);
        els.lastZoneFull.setAttribute("width", stopX - lastStartSceneX);

        const doneWidth = Math.max(0, Math.min(planeX, stopX) - lastStartSceneX);
        els.lastZoneDone.style.display = "";
        els.lastZoneDone.setAttribute("x", lastStartSceneX);
        els.lastZoneDone.setAttribute("width", doneWidth);

        els.lastStartTick.style.display = "";
        els.lastStartTick.setAttribute("transform", `translate(${lastStartSceneX} 0)`);

        els.lastSceneBadge.style.display = "";
        els.lastSceneBadge.setAttribute("transform", `translate(${(lastStartSceneX + stopX) / 2} 0)`);

        if(state.step === 4 && t >= T_STOP - 0.005){
          els.lastSceneBadgeText.textContent = "最后 4 s：48 m";
        } else {
          els.lastSceneBadgeText.textContent = "最后 4 s 区间";
        }
      } else {
        els.lastZoneFull.style.display = "none";
        els.lastZoneDone.style.display = "none";
        els.lastStartTick.style.display = "none";
        els.lastSceneBadge.style.display = "none";
      }
    }

    function updateTimeline(t){
      const tx = timeX(t);
      els.timeMarker.setAttribute("x1", tx);
      els.timeMarker.setAttribute("x2", tx);
      els.timeDot.setAttribute("cx", tx);

      if(state.showLast){
        const t2x = timeX(LAST_START_T);
        const t6x = timeX(T_STOP);
        els.lastTimeZone.style.display = "";
        els.lastTimeZone.setAttribute("x", t2x);
        els.lastTimeZone.setAttribute("width", t6x - t2x);
        els.lastBracket.style.display = "";
        els.bracketLine.setAttribute("x1", t2x);
        els.bracketLine.setAttribute("x2", t6x);
        els.bracketTickL.setAttribute("x1", t2x);
        els.bracketTickL.setAttribute("x2", t2x);
        els.bracketTickR.setAttribute("x1", t6x);
        els.bracketTickR.setAttribute("x2", t6x);
        els.bracketText.setAttribute("x", (t2x + t6x) / 2);
      } else {
        els.lastTimeZone.style.display = "none";
        els.lastBracket.style.display = "none";
      }
    }

    function updateReadouts(t){
      const v = velAt(t);
      const x = posAt(t);
      els.readT.textContent = t.toFixed(1);
      els.readV.textContent = v.toFixed(1);
      els.readX.textContent = x.toFixed(1);
      els.statusPill.textContent = v <= 0.01 ? "已停稳" : `t = ${t.toFixed(1)} s`;

      if(state.showLast){
        const within = Math.max(0, x - LAST_START_X);
        const isFinal = state.step === 4 && t >= T_STOP - 0.005;
        els.lastReadout.style.display = "";
        els.lastReadout.classList.toggle("final", isFinal);
        if(isFinal){
          els.lastReadout.innerHTML = `最后 4 s 内位移：<strong>${within.toFixed(1)} m</strong>`;
        } else {
          els.lastReadout.innerHTML = `最后 4 s 区间内已滑行：<strong>${within.toFixed(1)} m</strong>`;
        }
      } else {
        els.lastReadout.style.display = "none";
        els.lastReadout.innerHTML = "";
      }
    }

    function renderAll(){
      const vm = getViewMax();
      els.timeSlider.max = String(vm);

      if(state.lastViewMax !== vm){
        state.lastViewMax = vm;
        buildTimeTicks(vm);
        buildChartTicks(vm);
      }

      els.timeSlider.value = String(state.t);
      updateScene(state.t);
      updateTimeline(state.t);
      updateChart(state.t);
      updateReadouts(state.t);
    }

    function setStep(step){
      state.playing = false;
      state.step = step;
      state.showLast = step >= 3;
      const targets = [0, 0, 6, 2, 6];
      state.t = targets[step] ?? 0;
      updateStepButtons();
      updateAnswers();
      renderFormula();
      updatePlayButton();
      renderAll();
    }

    function updatePlayButton(){
      els.playBtn.textContent = state.playing ? "暂停" : "播放";
      els.playBtn.classList.toggle("primary", !state.playing);
    }

    function playTo(endT, duration){
      endT = clampT(endT);
      const startT = state.t;
      if(Math.abs(endT - startT) < 0.001){
        state.playing = false;
        updatePlayButton();
        renderAll();
        return;
      }
      state.playing = true;
      state.animStart = performance.now();
      state.animFrom = startT;
      state.animTo = endT;
      state.animDur = duration || Math.max(650, Math.abs(endT - startT) * 380);
      updatePlayButton();
      requestAnimationFrame(animTick);
    }

    function animTick(now){
      if(!state.playing) return;
      const p = Math.min(1, (now - state.animStart) / state.animDur);
      state.t = state.animFrom + (state.animTo - state.animFrom) * p;
      if(p >= 1){
        state.t = state.animTo;
        state.playing = false;
        updatePlayButton();
      }
      renderAll();
      if(state.playing){
        requestAnimationFrame(animTick);
      }
    }

    function togglePlay(){
      if(state.playing){
        state.playing = false;
        updatePlayButton();
        return;
      }
      const maxT = getViewMax();
      if(state.t >= maxT - 0.005){
        state.t = 0;
      }
      playTo(maxT, Math.max(700, (maxT - state.t) * 380));
    }

    els.stepBtns.forEach(btn => {
      btn.addEventListener("click", () => setStep(Number(btn.dataset.step)));
    });

    els.timeSlider.addEventListener("input", (e) => {
      state.playing = false;
      state.t = clampT(parseFloat(e.target.value));
      updatePlayButton();
      renderAll();
    });

    els.playBtn.addEventListener("click", togglePlay);
    els.resetBtn.addEventListener("click", () => setStep(0));

    els.formulaCard.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-demo]");
      if(!btn) return;
      const parts = btn.dataset.demo.split(",").map(Number);
      state.playing = false;
      state.t = clampT(parts[0]);
      renderAll();
      playTo(parts[1], Math.max(750, Math.abs(parts[1] - parts[0]) * 380));
    });

    setStep(0);
  })();
</script>
</body>
</html>
